<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
class Review extends Model { protected $appends=['media_details']; public function getMediaDetailsAttribute():array {return MediaAsset::where('owner_type','customer')->where('owner_id',$this->customer_id)->whereIn('url',array_merge($this->images??[],$this->videos??[]))->get(['url','file_name','mime_type','size_bytes','created_at'])->toArray();} protected $fillable = ['product_id','customer_id','order_item_id','rating','comment','seller_response','seller_responded_at','status','images','videos','rejection_note','moderated_at']; protected function casts(): array { return ['rating'=>'integer','seller_responded_at'=>'datetime','moderated_at'=>'datetime','images'=>'array','videos'=>'array']; } public function likes(): \Illuminate\Database\Eloquent\Relations\HasMany {return $this->hasMany(ReviewLike::class)->where('target_type','review');} public function responseLikes(): \Illuminate\Database\Eloquent\Relations\HasMany {return $this->hasMany(ReviewLike::class)->where('target_type','seller_response');} public function orderItem(): BelongsTo {return $this->belongsTo(OrderItem::class);} public function customer(): BelongsTo { return $this->belongsTo(Customer::class); } public function product(): BelongsTo { return $this->belongsTo(Product::class); } }
